package br.com.sideral.controller;
import javax.servlet.http.HttpServletResponse; import br.com.sideral.domain.DocumentRecord; import br.com.sideral.service.DocumentService; import com.lowagie.text.Document; import com.lowagie.text.Paragraph; import com.lowagie.text.pdf.PdfWriter; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.PathVariable; import org.springframework.web.bind.annotation.RequestMapping; import org.springframework.web.bind.annotation.RequestMethod;
@Controller @RequestMapping("/documentos")
public class DocumentExportController {
 @Autowired private DocumentService documents;
 @RequestMapping(value="/{id}/pdf",method=RequestMethod.GET) public void pdf(@PathVariable Long id,HttpServletResponse response)throws Exception {DocumentRecord record=required(id);response.setContentType("application/pdf");response.setHeader("Content-Disposition","attachment; filename=documento-"+id+".pdf");Document pdf=new Document();PdfWriter.getInstance(pdf,response.getOutputStream());pdf.open();pdf.add(new Paragraph(record.getTitle()+" - Revisão "+record.getRevision()));pdf.add(new Paragraph(""));pdf.add(new Paragraph(record.getContent()));pdf.close();}
 @RequestMapping(value="/{id}/word",method=RequestMethod.GET) public void word(@PathVariable Long id,HttpServletResponse response)throws Exception {DocumentRecord record=required(id);response.setContentType("application/msword");response.setHeader("Content-Disposition","attachment; filename=documento-"+id+".doc");response.getWriter().print("<html><head><meta charset='UTF-8'></head><body><h1>"+record.getTitle()+"</h1><p>Revisão: "+record.getRevision()+" | Autor: "+record.getAuthor()+"</p><hr><pre>"+record.getContent()+"</pre></body></html>");}
 private DocumentRecord required(Long id){DocumentRecord record=documents.get(id);if(record==null)throw new IllegalArgumentException("Documento não encontrado");return record;}
}